COMMENT ON TABLE serverless_student360_v2_catalog.gold.revenue_at_risk IS 'Expected tuition revenue at risk of loss from student attrition. revenue_at_risk_usd = expected_annual_tuition * ML risk_score. Use to quantify financial exposure by college and driver.';
COMMENT ON TABLE serverless_student360_v2_catalog.gold.finance_accounts IS 'Per-student account for Fall 2026: tuition_charged, aid_awarded, net_tuition, payments_received, balance_due, days_past_due, payment_plan_flag, delinquency_status (Current/Past Due/Delinquent/Payment Plan). Domestic tuition $25k, International $40k.';
COMMENT ON TABLE serverless_student360_v2_catalog.gold.aid_appeals IS 'Financial aid appeal requests. status is pending/approved/denied. requested_amount_usd is the additional aid requested. Use to manage the aid appeal queue.';
COMMENT ON TABLE serverless_student360_v2_catalog.gold.budget_vs_actual IS 'Departmental budget vs actual spend by college, fiscal_period (FY2025/FY2026), and category (Instruction, Student Services, Financial Aid, Facilities, Research). variance_usd = actual - budget; negative variance_pct = under budget.';
COMMENT ON TABLE serverless_student360_v2_catalog.gold.student_360 IS 'Student master record: demographics, program, college (faculty), gpa (US 4.0 scale), student_status, financial_aid flag, engagement (LMS) and risk_level. Joins to finance tables and student_risk_predictions on student_id.';
SELECT 1;
